// C++98/03 Style: Nested typedef
template<typename T>
struct MyList_Typedef {
  typedef std::list<T> type;
};

// C++11 Style: Alias Template
template<typename T>
using MyList_Using = std::list<T>;

// Usage within another template
template<typename T>
class Widget {
private:
  // 'typename' and '::type' are required for the dependent type
  typename MyList_Typedef<T>::type list1;

  // Alias template creates a non-dependent type; much cleaner
  MyList_Using<T> list2;
};
